<?php get_header(); ?><main id="conteudo"><?php while(have_posts()){the_post(); ?><article class="section article-page <?php echo esc_attr(get_post_type()); ?>"><a class="breadcrumb" href="<?php echo esc_url(home_url(get_post_type()==='post'?'/blog/':'/')); ?>">← <?php echo get_post_type()==='post'?'Voltar ao blog':'Voltar ao início'; ?></a><p class="eyebrow"><?php echo get_post_type()==='mdr_socio'?esc_html(get_post_meta(get_the_ID(),'mdr_role',true)):(get_post_type()==='mdr_premio'?'Reconhecimento institucional':'MDR em perspectiva'); ?></p><h1><?php the_title(); ?></h1><?php if(get_post_type()==='post'){ ?><div class="article-byline"><span><?php echo esc_html(get_the_author()); ?></span><time datetime="<?php echo esc_attr(get_the_date('c')); ?>"><?php echo esc_html(get_the_date('d \d\e F \d\e Y')); ?></time></div><?php } ?><?php if(has_post_thumbnail()){ ?><div class="article-featured"><?php the_post_thumbnail('large'); ?></div><?php } ?><div class="prose"><?php the_content(); ?></div><?php if(get_post_type()==='mdr_socio'){ ?><div class="social-links"><?php mdr_social(get_the_ID()); ?></div><?php } ?></article><?php } ?></main><?php get_footer(); ?>
